const lockChannelForValidation = `-- name: LockChannelForValidation :one
SELECT c.id
FROM channel_offers o
JOIN channel_models cm ON cm.id = o.channel_model_id
JOIN channels c ON c.id = cm.channel_id
JOIN accounts actor ON actor.id = $1
WHERE o.id = $2 AND o.status <> 'deleted' AND c.status <> 'deleted'
	AND actor.status = 'active' AND NOT actor.must_change_password
	AND (c.owner_account_id = actor.id OR actor.is_admin)
FOR UPDATE OF c
`

type LockChannelForValidationParams struct {
	ActorAccountID string
	OfferID        string
}

// 先锁渠道再锁报价，与配置变更同序，目标是一致的 Base URL、凭据与验证版本快照。
func (q *Queries) LockChannelForValidation(ctx context.Context, arg LockChannelForValidationParams) (string, error) {
	row := q.db.QueryRow(ctx, lockChannelForValidation, arg.ActorAccountID, arg.OfferID)
	var id string
	err := row.Scan(&id)
	return id, err
}

