const replaceCredentialCiphertext = `-- name: ReplaceCredentialCiphertext :execrows
UPDATE channel_credentials SET key_id = $1, nonce = $2, ciphertext = $3, updated_at = now()
WHERE channel_id = $4 AND credential_version = $5
	AND key_id = $6 AND nonce = $7 AND ciphertext = $8
`

type ReplaceCredentialCiphertextParams struct {
	KeyID             string
	Nonce             []byte
	Ciphertext        []byte
	ChannelID         string
	CredentialVersion int64
	OldKeyID          string
	OldNonce          []byte
	OldCiphertext     []byte
}

// 仅当库内密文仍等于读取时的旧值才替换（compare-and-swap）。
func (q *Queries) ReplaceCredentialCiphertext(ctx context.Context, arg ReplaceCredentialCiphertextParams) (int64, error) {
	result, err := q.db.Exec(ctx, replaceCredentialCiphertext,
		arg.KeyID,
		arg.Nonce,
		arg.Ciphertext,
		arg.ChannelID,
		arg.CredentialVersion,
		arg.OldKeyID,
		arg.OldNonce,
		arg.OldCiphertext,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const resetChannelOfferValidation = `-- name: ResetChannelOfferValidation :exec
UPDATE channel_offers o SET validation_version = validation_version + 1,
	validation_attempt_seq = 0, updated_at = now()
FROM channel_models cm
WHERE o.channel_model_id = cm.id AND cm.channel_id = $1 AND o.status <> 'deleted'
`

// 配置、吊销凭据或删除渠道后，渠道下所有未删除报价的验证作废并重新计数。
func (q *Queries) ResetChannelOfferValidation(ctx context.Context, channelID string) error {
	_, err := q.db.Exec(ctx, resetChannelOfferValidation, channelID)
	return err
}

