const updateSiblingOffers = `-- name: UpdateSiblingOffers :execrows
UPDATE channel_offers SET
	upstream_model_id = CASE WHEN id = $1 THEN $2::text ELSE upstream_model_id END,
	version = version + 1,
	validation_version = validation_version + CASE WHEN id = $1 AND $3::boolean THEN 1 ELSE 0 END,
	validation_attempt_seq = CASE WHEN id = $1 AND $3::boolean THEN 0 ELSE validation_attempt_seq END,
	updated_at = now()
WHERE channel_model_id = $4 AND status <> 'deleted'
`

type UpdateSiblingOffersParams struct {
	OfferID         string
	UpstreamModelID string
	UpstreamChanged bool
	ChannelModelID  string
}

// 倍率变化时同一渠道模型下所有未删除报价一起升版本；仅目标报价可能改上游模型并重置验证。
func (q *Queries) UpdateSiblingOffers(ctx context.Context, arg UpdateSiblingOffersParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateSiblingOffers,
		arg.OfferID,
		arg.UpstreamModelID,
		arg.UpstreamChanged,
		arg.ChannelModelID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertCredential = `-- name: UpsertCredential :exec
INSERT INTO channel_credentials (channel_id, credential_version, key_id, nonce, ciphertext)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (channel_id) DO UPDATE SET
	credential_version = EXCLUDED.credential_version,
	key_id = EXCLUDED.key_id,
	nonce = EXCLUDED.nonce,
	ciphertext = EXCLUDED.ciphertext,
	configured_at = now(), updated_at = now()
`

type UpsertCredentialParams struct {
	ChannelID         string
	CredentialVersion int64
	KeyID             string
	Nonce             []byte
	Ciphertext        []byte
}

func (q *Queries) UpsertCredential(ctx context.Context, arg UpsertCredentialParams) error {
	_, err := q.db.Exec(ctx, upsertCredential,
		arg.ChannelID,
		arg.CredentialVersion,
		arg.KeyID,
		arg.Nonce,
		arg.Ciphertext,
	)
	return err
}

